const D = { hue: 300, energy: .6, speed: 1, density: .6, scale: 1, x: .5, y: .5, n: 18, drift: .5, style: 'biolum', pal: 'deep', act: 'rise', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(3, Math.min(40, Math.round(P.n)));
const ho = P.hue - 300;

const PAL = {
  deep:  { core:[188,70,100], edge:[300,72,90], tent:[210,60,88], spark:[168,60,100], water:[214,66,7] },
  abyss: { core:[266,64,96], edge:[224,74,86], tent:[248,60,82], spark:[286,50,100], water:[240,70,6] },
  ember: { core:[36,80,100], edge:[8,78,92],  tent:[22,70,86],  spark:[46,72,100], water:[8,60,7] },
  toxic: { core:[74,78,100], edge:[128,72,88], tent:[96,64,84], spark:[64,70,100], water:[150,60,6] },
  pearl: { core:[36,20,100], edge:[330,34,96], tent:[300,24,90], spark:[200,20,100], water:[250,30,9] } };
const pc = PAL[P.pal] || PAL.deep;
const tint = c => [hw(c[0] + ho), c[1], c[2]];
const sty = P.style;
const xray = sty === 'xray';
const ink = sty === 'ink';
const neon = sty === 'neon';
const thermal = sty === 'thermal';

const wk = width + 'x' + height + sty + P.pal + Math.round(P.hue);
if (!S.wash || S.wk !== wk) {
  if (!S.wash) S.wash = createGraphics(width, height);
  else S.wash.resizeCanvas(width, height);
  const g = S.wash; g.clear();
  g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke();
  const wc = tint(pc.water);
  for (let yy = 0; yy < height; yy++) {
    const t = yy / height;
    g.fill(hw(wc[0] - t * 14), wc[1] * (1 - t * .4), wc[2] * (.5 + t * 1.3), 30 + t * 34);
    g.rect(0, yy, width, 1);
  }
  if (!xray) { g.blendMode(g.ADD);
    for (let i = 0; i < 5; i++) { const rx = fr(i * 7 + 3) * width;
      g.fill(tint(pc.edge)[0], 24, 60, 3 + fr(i) * 3);
      g.quad(rx, 0, rx + u * .04, 0, rx + u * .14, height, rx - u * .06, height); }
    g.blendMode(g.BLEND); }
  S.wk = wk;
}
image(S.wash, 0, 0);

if (!S.j || S.jn !== N || S.jseed !== P.seed) {
  S.j = [];
  for (let i = 0; i < N; i++) {
    S.j.push({
      bx: fr(i * 4 + 1),
      y0: fr(i * 4 + 2),
      z: .25 + fr(i * 4 + 3) * .75,
      ph: fr(i * 4 + 5) * TAU,
      rate: .5 + fr(i * 4 + 7) * .8,
      tw: fr(i * 4 + 9) });
  }
  S.j = S.j.sort((a, b) => a.z - b.z);
  S.jn = N; S.jseed = P.seed;
}

const inten = .55 + .6 * K.intensity;
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const CUR = {
  rise:  [[0,-1,0],[ .1,-1,.05],[-.1,-.9,.1],[0,-1,0],[.15,-.8,.15],[-.05,-1,.05],[.1,-.9,.1],[0,-1,.05]],
  swirl: [[.4,-.3,.4],[-.4,-.3,.5],[.5,-.2,.4],[-.5,-.3,.6],[.4,-.2,.5],[-.4,-.3,.4],[.5,-.2,.5],[-.3,-.3,.5]],
  tide:  [[1,-.2,0],[.6,-.3,.1],[-.6,-.2,0],[-1,-.3,.1],[.8,-.2,0],[.4,-.3,.1],[-.8,-.2,0],[-.4,-.3,.1]] };
const cur = (CUR[P.act] || CUR.rise)[sec];
const riseSpd = (.02 + .05 * P.drift) * P.speed;
const swayGlobal = K.t * (.15 + .3 * P.drift) * P.speed;

const tentBase = xray ? 4 : Math.round(4 + P.density * 5);

for (const j of S.j) {
  const z = j.z;
  const R = u * (.05 + .11 * z) * P.scale;
  const span = 1 + R / height * 2;
  let yf = (j.y0 - K.t * riseSpd * (.5 + z) * (-cur[1]));
  yf = ((yf % span) + span) % span;
  const py = (yf) * (height + 2 * R) - R;
  const swirl = Math.sin(K.t * (.4 + z * .3) + j.ph) * cur[2];
  const px = (j.bx * width
    + Math.sin(swayGlobal + j.ph) * u * .04 * (.3 + z)
    + cur[0] * z * u * .12 * Math.sin(K.t * .1 + j.tw * 6)
    + swirl * u * .06);
  const wx = ((px % (width + R * 2)) + (width + R * 2)) % (width + R * 2) - R;

  const pph = K.beat * j.rate * P.speed * .5 + K.t * .12 * j.rate + j.ph;
  let pulse = .5 + .5 * Math.sin(pph * TAU);
  pulse = Math.pow(pulse, 1.6);
  const contract = pulse * (.4 + .5 * P.energy);
  const jet = (A.bass * .4 + K.pulse * .1);
  const alpha = (thermal || neon ? 60 : 46) * (.4 + z * .8) + jet * 20;

  const bellW = R * (1.02 - .32 * contract) * 2;
  const bellH = R * (.78 + .55 * contract) * 2;

  push();
  translate(wx, py);
  const cCore = tint(pc.core), cEdge = tint(pc.edge), cTent = tint(pc.tent), cSpark = tint(pc.spark);

  const nt = tentBase;
  const tlen = bellH * (1.1 + 1.6 * z) * (1 + .3 * P.energy);
  for (let s = 0; s < nt; s++) {
    const off = (s / (nt - 1) - .5) * bellW * .74;
    const swim = swayGlobal * 3 + j.tw * 10 + s * .8;
    if (xray) { stroke(cEdge[0], cEdge[1], cEdge[2], alpha * .8); strokeWeight(.8); noFill(); }
    else if (ink) { stroke(cTent[0], cTent[1] * .5, cTent[2] * .7, alpha * .7); strokeWeight(R * .05); noFill(); }
    else { stroke(cTent[0], cTent[1], cTent[2], alpha * .85); strokeWeight(R * (.05 + .04 * z)); noFill(); }
    beginShape();
    const segN = 5;
    for (let g2 = 0; g2 <= segN; g2++) {
      const tt = g2 / segN;
      const sx = off + Math.sin(swim + tt * 3.2 + contract * 1.5) * bellW * .12 * tt;
      const sy = bellH * .32 + tlen * tt;
      curveVertex(sx, sy);
    }
    endShape();
  }
  if (!xray) {
    for (let s = 0; s < 3; s++) {
      const off = (s - 1) * bellW * .12;
      stroke(cCore[0], cCore[1] * .8, cCore[2], alpha * .9); strokeWeight(R * .06); noFill();
      beginShape();
      for (let g2 = 0; g2 <= 4; g2++) { const tt = g2 / 4;
        curveVertex(off + Math.sin(swayGlobal * 4 + s + tt * 4) * bellW * .06, bellH * .3 + tlen * .45 * tt); }
      endShape();
    }
  }

  if (!xray && !ink) {
    push(); blendMode(ADD); noStroke();
    for (let r = 0; r < 3; r++) {
      const gc = thermal ? [hw(20 + r * 60), 80, 100] : cEdge;
      fill(gc[0], gc[1] * .7, gc[2], (10 + jet * 14) * (1 - r * .28) * (.5 + z * .6));
      ellipse(0, 0, bellW * (1.5 + r * .5), bellH * (1.4 + r * .5));
    }
    blendMode(BLEND); pop();
  }

  if (xray) {
    noFill(); stroke(cEdge[0], cEdge[1], cEdge[2], alpha + 20); strokeWeight(1);
    for (let r = 1; r <= 3; r++) arc(0, 0, bellW * r / 3, bellH * r / 3, Math.PI, TAU);
    for (let a = 0; a <= 6; a++) { const aa = Math.PI + a / 6 * Math.PI;
      line(0, 0, Math.cos(aa) * bellW / 2, Math.sin(aa) * bellH / 2); }
    stroke(cCore[0], cCore[1], cCore[2], alpha + 30);
    line(-bellW / 2, 0, bellW / 2, 0);
  } else {
    push(); if (thermal || neon) blendMode(ADD);
    if (ink) { noStroke(); fill(cTent[0], cTent[1] * .4, cTent[2] * .8, alpha * .7);
      arc(0, 0, bellW, bellH, Math.PI, TAU, CHORD); }
    else {
      noStroke();
      for (let r = 3; r >= 0; r--) {
        const tt = r / 3;
        const col = thermal ? [hw(200 - tt * 190), 74, 100] : [hw(cEdge[0] + (cCore[0] - cEdge[0]) * (1 - tt)), cEdge[1] * (.6 + tt * .4), cEdge[2]];
        fill(col[0], col[1], col[2], alpha * (neon ? .5 : .8) * (1 - tt * .3));
        arc(0, 0, bellW * (1 - tt * .5), bellH * (1 - tt * .42), Math.PI, TAU, CHORD);
      }
      fill(cCore[0], cCore[1] * .8, cCore[2], alpha + 14 + jet * 20);
      ellipse(0, -bellH * .06, bellW * .28, bellH * .3);
    }
    noFill(); stroke(cEdge[0], cEdge[1], Math.min(100, cEdge[2] + 8), alpha + (neon ? 40 : 18));
    strokeWeight(neon ? R * .05 : R * .03);
    arc(0, 0, bellW, bellH, Math.PI, TAU);
    noStroke();
    const nd = 7;
    for (let d = 0; d <= nd; d++) {
      const aa = Math.PI + d / nd * Math.PI;
      const dx = Math.cos(aa) * bellW / 2, dy = Math.sin(aa) * bellH / 2;
      const tw = .5 + .5 * Math.sin(K.t * 3 + d + j.ph + A.treble * 4);
      fill(cSpark[0], cSpark[1], cSpark[2], (alpha + 20) * tw);
      circle(dx, dy, R * (.07 + .05 * tw));
    }
    pop();
  }
  pop();
}
blendMode(BLEND);
